use std::collections::VecDeque;impl Solution{pub fn can_finish(n:i32,p:Vec<Vec<i32>>)->bool{let n=n as usize;let mut g=vec![vec![];n];let mut d=vec![0;n];for e in p{g[e[1]as usize].push(e[0]as usize);d[e[0]as usize]+=1;}let mut q=VecDeque::new();for i in 0..n{if d[i]==0{q.push_back(i)}}let mut c=0;while let Some(u)=q.pop_front(){c+=1;for &v in &g[u]{d[v]-=1;if d[v]==0{q.push_back(v)}}}c==n}}
